// ---- saved choices (theme / variant): survive a restart and reach the always-on screen ----
const dcGet = (k) => {
  try { const v = Number(zosFs.readFileSync({ path: 'dc_' + k + '.txt', options: { encoding: 'utf8' } })); if (v) return v } catch (e) {}
  try { if (typeof hmFS !== 'undefined') return Number(hmFS.SysProGetInt(k)) || 0 } catch (e) {}
  return 0
}
const dcSet = (k, v) => {
  try { zosFs.writeFileSync({ path: 'dc_' + k + '.txt', data: String(v), options: { encoding: 'utf8' } }) } catch (e) {}
  try { if (typeof hmFS !== 'undefined') hmFS.SysProSetInt(k, v) } catch (e) {}
}

